const payResp = $('HTTP: Read Pending Payments (Supabase)').first().json || {};
const prodResp = $('HTTP: Read Products (Supabase)').first().json || {};
const pausedResp = $('HTTP: Read Paused Chats').first().json || {};
const rows = Array.isArray(payResp.rows) ? payResp.rows : [];
const FIXED_CONFIRMATION = 'تم تأكيد الدفع.';
function normLbl(s) { return String(s || '').replace(/\s+/g, ' ').trim(); }
const pdfEntries = [];
for (const p of prodResp.products || []) {
  const c = String(p.product_code || '').trim().toLowerCase();
  const u = String(p.pdf_url || '').trim();
  const lbl = normLbl(p.label_ar).toLowerCase();
  if (!u || /REPLACE/i.test(u)) continue;
  pdfEntries.push({ code: c, url: u, label: lbl });
}
const pdfByCode = {};
for (const e of pdfEntries) { if (e.code) pdfByCode[e.code] = e.url; }
function resolvePdfUrl(codeRaw, labelRaw) {
  const code = String(codeRaw || '').trim().toLowerCase();
  const pl = normLbl(labelRaw).toLowerCase();
  let url = code ? (pdfByCode[code] || '') : '';
  if (!url && code) {
    const hit = pdfEntries.find(e => e.label === code || e.code === code);
    if (hit) url = hit.url;
  }
  if (!url && pl) {
    const hit = pdfEntries.find(e => e.label && (pl === e.label || pl.includes(e.label) || e.label.includes(pl)));
    if (hit) url = hit.url;
  }
  return url || '';
}
function normalizePhone(v) {
  let d = String(v ?? '').replace(/\D/g, '');
  if (!d) return '';
  if (d.startsWith('20') && d.length === 12) return d;
  if (d.startsWith('0') && d.length === 11) return '20' + d.slice(1);
  if (!d.startsWith('20') && d.length === 10) return '20' + d;
  return d;
}
function isPhonePaused(phone) {
  const pr = Array.isArray(pausedResp.rows) ? pausedResp.rows : [];
  const p = normalizePhone(phone);
  const now = Date.now();
  for (const row of pr) {
    if (normalizePhone(row.phone) !== p) continue;
    if (row.active === false) continue;
    const exp = new Date(row.expires_at).getTime();
    if (Number.isFinite(exp) && exp > now) return true;
  }
  return false;
}
const out = [];
const processed_at = new Date().toISOString();
for (const r of rows) {
  const targetTs = String(r.timestamp || r.id || '').trim();
  const done = Boolean(r.done);
  const status = String(r.whatsapp_status || '').trim().toLowerCase();
  const phone = normalizePhone(r.phone);
  let precheckError = '';
  if (!done) precheckError = 'payment_not_confirmed';
  else if (status === 'sent') precheckError = 'already_sent';
  else if (status === 'dead_letter') precheckError = 'dead_letter';
  else if (!phone) precheckError = 'missing_phone';
  else if (!/^20\d{10}$/.test(phone)) precheckError = 'invalid_phone';
  else if (isPhonePaused(phone)) precheckError = 'human_handoff_paused';
  const pdfUrl = resolvePdfUrl(r.product_code, r.product_label);
  const confirmation_text = pdfUrl
    ? FIXED_CONFIRMATION + '\n\nرابط تحميل الكتاب (PDF أو مجلد Drive):\n' + pdfUrl
    : FIXED_CONFIRMATION + '\n\nلم يُعثر على رابط تحميل لهذا الكتاب؛ سنتواصل معك لاحقًا.';
  const should_send = precheckError === '';
  out.push({
    json: {
      ok: true,
      form_timestamp: targetTs,
      phone,
      confirmation_text,
      pdf_url: pdfUrl,
      product_code: r.product_code,
      should_send,
      precheck_error: precheckError,
      processed_at,
      stage: should_send ? 'ready_to_send' : 'precheck_failed'
    }
  });
}
return out;

const resp = $input.first().json;
let prep;
try {
  prep = $('Code: Expand Pending To Items').item.json;
} catch (e) {
  prep = {};
}
const messageId =
  resp?.key?.id ||
  resp?.message?.key?.id ||
  resp?.data?.key?.id ||
  resp?.messages?.[0]?.key?.id ||
  '';
const base = {
  form_timestamp: prep.form_timestamp,
  phone: prep.phone,
  confirmation_text: prep.confirmation_text,
  processed_at: prep.processed_at
};
if (!messageId) {
  const errMsg =
    resp?.error?.message ||
    resp?.message ||
    (resp?.error ? String(resp.error) : '') ||
    'no_outbound_message_id';
  return [{ json: { ...base, send_ok: false, send_error: errMsg, evolution_response: resp } }];
}
return [{ json: { ...base, send_ok: true, message_id: messageId, send_error: '' } }];
